import { addMonths, dateInMonth } from './dates';
import type { RecurringRule, RecurringRuleDraft, TransactionDraft, YearMonth } from './types';

/**
 * Months a rule should have generated by `currentMonth`: from its start month up to the
 * current month (or its end month, if earlier). Empty when the rule starts in the future.
 */
export function monthsDue(rule: Pick<RecurringRule, 'startMonth' | 'endMonth'>, currentMonth: YearMonth): YearMonth[] {
  const last = rule.endMonth !== null && rule.endMonth < currentMonth ? rule.endMonth : currentMonth;
  const months: YearMonth[] = [];
  for (let month = rule.startMonth; month <= last; month = addMonths(month, 1)) months.push(month);
  return months;
}

/**
 * Months still to generate. A month that was generated once never comes back, even if its
 * movement was deleted afterwards: that is what keeps generation idempotent.
 */
export function pendingMonths(
  rule: Pick<RecurringRule, 'startMonth' | 'endMonth'>,
  generated: ReadonlySet<YearMonth>,
  currentMonth: YearMonth,
): YearMonth[] {
  return monthsDue(rule, currentMonth).filter((month) => !generated.has(month));
}

/** The normal movement a rule creates for a month. Days the month lacks fall on its last day. */
export function transactionFromRule(rule: RecurringRule, month: YearMonth): TransactionDraft {
  return {
    type: rule.type,
    amount: rule.amount,
    date: dateInMonth(month, rule.dayOfMonth),
    accountId: rule.accountId,
    categoryId: rule.categoryId,
    title: rule.title,
    tagIds: [...rule.tagIds],
    recurringRuleId: rule.id,
    recurringMonth: month,
  };
}

/**
 * Which movements already created by a rule take an edit of the rule:
 * - 'future': none, only the months still to come (the default).
 * - 'currentMonth': also this month's movement.
 * - 'allGenerated': every movement the rule has created and still exists, overwriting manual edits.
 */
export type RuleChangeScope = 'future' | 'currentMonth' | 'allGenerated';

/** Whether an edit changes what the generated movement looks like (not just the start or end month). */
export function changesMovement(before: RecurringRuleDraft, after: RecurringRuleDraft): boolean {
  return (
    before.type !== after.type ||
    before.amount !== after.amount ||
    before.dayOfMonth !== after.dayOfMonth ||
    before.accountId !== after.accountId ||
    before.categoryId !== after.categoryId ||
    (before.title ?? '') !== (after.title ?? '') ||
    before.tagIds.length !== after.tagIds.length ||
    before.tagIds.some((id, i) => id !== after.tagIds[i])
  );
}
